const base = <billingreply.result> ?? <techsupportreply.result> ?? <salesreply.result> ?? <returnreply.result> ?? <shippingreply.result> ?? <otherreply.result> ?? "Thank you for reaching out. A member of our team will be in contact with you shortly.";
const sentiment = <analyzesentiment.sentiment>;
if (sentiment === "Very Angry") {
  return "We're very sorry for the frustration you've experienced, and we've marked your request as a priority. " + base;
}
return base;

const category =
  <billingreply.result> != null ? "Billing" :
  <techsupportreply.result> != null ? "Technical Support" :
  <salesreply.result> != null ? "Sales" :
  <returnreply.result> != null ? "Product Return" :
  <shippingreply.result> != null ? "Shipping" : "Other";
const shoes = <checkshoes.references_shoes>;
const shoeReason = <checkshoes.reason>;
const reasoning = String(shoes) === "false"
  ? `Not about shoes (Claude shoe check: ${shoeReason ?? "no reason given"}) - sent to Other with the shoes-only reply`
  : (<classifyrequest.reasoning> ?? "");
return {
  message: <start.input> ?? "",
  category,
  reply: <sendreply.result>,
  router_reasoning: reasoning,
  conversation_id: <start.conversationId> ?? "",
  source: "Claude",
  sentiment: <analyzesentiment.sentiment> ?? null,
  sentiment_reason: <analyzesentiment.reason> ?? ""
};

const shoes = <checkshoes.references_shoes>;
if (String(shoes) === "false") {
  return "Thank you for reaching out! We sell only men's and women's sport shoes, so we can only help with questions about our shoes. If your message is about a pair of our shoes or a shoe order, please tell us which shoes it's about and we'll be glad to help.";
}
return "Thank you for reaching out! We specialize in men's and women's sport shoes, so we're only able to help with questions about our shoes and your orders with us. If your question is about one of our shoes or an order, please send us a few more details and a member of our customer service team will be in contact with you shortly.";

